# Palindrome check using stack
def is_palindrome(word):
    stack = list(word)
    reversed_word = ''
    while stack:
        reversed_word += stack.pop()
    return word == reversed_word

print(is_palindrome('madam'))   # True
print(is_palindrome('hello'))   # False

# Matching brackets using stack
def matching_brackets(expr):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in expr:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return len(stack) == 0

print(matching_brackets("(a+b)*[c-d]"))  # True
print(matching_brackets("(a+b"))          # False
